    -- binds the table owner and every SECURITY DEFINER path equally.
    ('guard_rebook_round_intent_append_only',          '',                                                                 'A','rebook_rounds','guard', false,'v','none', false),
    -- Domain P: the product-relation guard. Since Stage 7.4-A its one Domain-A fact (the round
