    ('guard_notification_event_type_authority',        '',                                                                 'N','notification_outbox','guard', false,'v','none', false);
  -- ── Tables: existence, single owner, RLS + FORCE RLS, no policies, zero effective privileges.
  FOR v_tbl IN SELECT unnest(v_tables) LOOP
    SELECT c.relowner::regrole::name INTO v_owner
      FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
     WHERE n.nspname = 'public' AND c.relname = v_tbl;
    IF v_owner IS NULL THEN
      RAISE EXCEPTION 'ABC-27 assert: public.% was not created', v_tbl;
    END IF;
    IF v_towner IS NULL THEN v_towner := v_owner;
    ELSIF v_owner <> v_towner THEN
      RAISE EXCEPTION 'ABC-27 assert: public.% is owned by % but the unit''s other tables are owned by %', v_tbl, v_owner, v_towner;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
                    WHERE n.nspname='public' AND c.relname=v_tbl AND c.relrowsecurity) THEN
      RAISE EXCEPTION 'ABC-27 assert: RLS is not enabled on public.%', v_tbl;
